/* @autogenerated */
import { Directive, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { endWith, ignoreElements, map, Observable, of, Subscription, switchMap } from 'rxjs';
import { ActionParam, ActionParamValues, ActionParamsDialogService } from '../dialog/action-params-dialog.service';
import { ConfirmDialogService } from '../dialog/confirm-dialog.service';
import { NotifyService } from '../notify/notify.service';
import { BaseAction } from './base-action';

/**
 * Acción que pide confirmación, ejecuta `execute(items)`, avisa del resultado y cierra el contenedor.
 *
 * Textos (`<scope>.action.<textKey>.*`): `title`, `content`, `okBtn`, `cancelBtn`, `report`, `dismiss`.
 *
 * Con `params`, en lugar de la confirmación se abre un diálogo que los pide, y sus valores llegan a `execute`.
 */
@Directive()
export abstract class ConfirmAction<T = any> extends BaseAction<T> {
  private readonly confirmDialog = inject(ConfirmDialogService);
  private readonly paramsDialog = inject(ActionParamsDialogService);
  private readonly notify = inject(NotifyService);
  private pending?: Subscription;

  /** Datos que se piden antes de ejecutar la acción; sin ellos, solo se confirma. Se lee al ejecutarla. */
  protected get params(): readonly ActionParam[] {
    return [];
  }

  protected abstract execute(items: T[], params: ActionParamValues): Observable<unknown>;

  run(): void {
    const items = this.selection();
    // Cancelar la suscripción cierra el diálogo que siguiera abierto
    this.pending?.unsubscribe();
    this.pending = this.ask()
      .pipe(
        switchMap((params) => (params ? this.execute(items, params).pipe(ignoreElements(), endWith(true)) : of(false))),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe((done) => {
        this.container()?.close();
        if (done) {
          this.notify.success(this.textKeyOf('report') ?? 'common.action.report', undefined, this.textKeyOf('dismiss'));
        }
      });
  }

  /** Los valores de los parámetros (vacíos si no hay) al aceptar, o `null` al cancelar. */
  private ask(): Observable<ActionParamValues | null> {
    const params = this.params;
    if (params.length) {
      return this.paramsDialog.ask({
        title: this.text('title'),
        message: this.text('content'),
        ok: this.text('okBtn'),
        cancel: this.text('cancelBtn'),
        params,
      });
    }
    return this.confirmDialog
      .confirm({
        messageKey: this.textKeyOf('content') ?? 'common.action.content',
        titleKey: this.textKeyOf('title'),
        okKey: this.textKeyOf('okBtn'),
        cancelKey: this.textKeyOf('cancelBtn'),
      })
      .pipe(map((ok) => (ok ? {} : null)));
  }
}
